export function getSpeechPrompt(type = 'listening') {
  const lang = getInterfaceLanguage();
  const bundle = SPEECH_PROMPTS[type] || SPEECH_PROMPTS['listening'];
  return bundle[lang] || bundle['en'] || bundle['ru'];
}

export function t(key) {
  if (key === 'speech_listening') return getSpeechPrompt('listening');
  if (key === 'speech_evaluating') return getSpeechPrompt('evaluating');
  if (key === 'speech_not_recognized') return getSpeechPrompt('retry');
  if (key === 'speech_tap_to_speak') return getSpeechPrompt('tap_to_speak');
  if (key === 'review_repeat') return getSpeechPrompt('review_repeat');
  if (key === 'review_know') return getSpeechPrompt('review_know');
  if (key === 'fav_autoplay_listen') {
    const lang = getInterfaceLanguage();
    const map = {
      ru: "Слушать", uk: "Слухати", en: "Listen", de: "Anhören", es: "Escuchar",
      fr: "Écouter", pl: "Słuchaj", tr: "Dinle", it: "Ascolta", ro: "Ascultă",
      bg: "Слушай", hu: "Hallgatás", el: "Ακούστε", da: "Lyt", ga: "Éist",
      lv: "Klausīties", lt: "Klausytis", sr: "Слушај", pt: "Ouvir", sk: "Počúvať",
      sl: "Poslušaj", fi: "Kuuntele", hr: "Slušaj", cs: "Poslouchat", sv: "Lyssna",
      et: "Kuula", mt: "Isma'", nl: "Luisteren"
    };
    return map[lang] || map['en'] || "Listen";
  }
  if (key === 'fav_autoplay_stop') {
    const lang = getInterfaceLanguage();
    const map = {
      ru: "Стоп", uk: "Стоп", en: "Stop", de: "Stopp", es: "Parar",
      fr: "Arrêter", pl: "Stop", tr: "Durdur", it: "Stop", ro: "Stop",
      bg: "Стоп", hu: "Állj", el: "Διακοπή", da: "Stop", ga: "Stad",
      lv: "Apturēt", lt: "Sustabdyti", sr: "Стоп", pt: "Parar", sk: "Stop",
      sl: "Ustavi", fi: "Pysäytä", hr: "Stop", cs: "Stop", sv: "Stopp",
      et: "Peata", mt: "Ieqaf", nl: "Stop"
    };
    return map[lang] || map['en'] || "Stop";
  }
  if (key === 'word_notes_title') {
    const lang = getInterfaceLanguage();
    if (lang === 'ru') return 'Примечание';
    if (lang === 'uk') return 'Примітка';
    if (lang === 'de') return 'Hinweis';
    if (lang === 'es' || lang === 'pt' || lang === 'it') return 'Nota';
    if (lang === 'fr') return 'Remarque';
    if (lang === 'pl') return 'Uwaga';
    if (lang === 'tr') return 'Not';
    return 'Note';
  }

  const lang = getInterfaceLanguage();
  const dict = translations[lang] || translations['en'];
  return dict[key] || translations['en'][key] || key;
}

export function getWordTranslation(wordObj) {
  if (!wordObj) return '';
  const lang = getInterfaceLanguage();
  if (wordObj.translations && wordObj.translations[lang]) {
    const localized = wordObj.translations[lang];
    if (typeof localized === 'string' && !localized.includes('\ufffd')) {
      return localized;
    }
  }
  if (typeof wordObj.translation === 'string' && !wordObj.translation.includes('\ufffd')) {
    return wordObj.translation;
  }
  return (wordObj.translation || '').replace(/\ufffd+/g, '');
}


export function getWordNotes(wordObj) {
  if (!wordObj) return '';

  // 1. Personal user note has highest priority
  if (typeof wordObj.user_note === 'string' && wordObj.user_note.trim().length > 0) {
    return wordObj.user_note.trim();
  }
  if (typeof localStorage !== 'undefined') {
    try {
      const userNotes = JSON.parse(localStorage.getItem('myduo_user_notes') || '{}');
      const wId = wordObj.id ? String(wordObj.id) : '';
      const wText = wordObj.word ? String(wordObj.word).toLowerCase().trim() : '';
      const personalNote = (wId && userNotes[wId]) || (wText && userNotes[wText]);
      if (personalNote && typeof personalNote === 'string' && personalNote.trim().length > 0) {
        return personalNote.trim();
      }
    } catch (e) {}
  }

  const lang = getInterfaceLanguage();
  if (wordObj.all_notes && typeof wordObj.all_notes === 'object') {
    const n = wordObj.all_notes[lang];
    if (n && typeof n === 'string' && n.trim().length > 0) return n.trim();
  }
  // Check direct column properties (e.g. notes for ru, notes_uk, notes_de, notes_es, etc.)
  if (lang === 'ru') {
    return (wordObj.notes && typeof wordObj.notes === 'string') ? wordObj.notes.trim() : '';
  }
  const langKey = `notes_${lang}`;
  if (wordObj[langKey] && typeof wordObj[langKey] === 'string' && wordObj[langKey].trim().length > 0) {
    return wordObj[langKey].trim();
  }
  return '';
}

